const res = $input.first().json;
const ups = Array.isArray(res.result) ? res.result : [];
if (!res.ok || ups.length === 0) return [];
return [{ json: { max_id: Math.max(...ups.map(u => u.update_id)), updates: ups } }];

const ups = $('Preparar').first().json.updates;
return ups
  .filter(u => u.message && typeof u.message.text === 'string' && u.message.chat && u.message.chat.type === 'private')
  .map(u => ({ json: { chat_id: u.message.chat.id, text: u.message.text } }));

const t = String($json.text ?? '').trim();
const partes = t.split(/\s+/);
const validos = ['/start', '/estaciones', '/suscribir', '/baja'];
const cmd = (partes[0] || '').toLowerCase().split('@')[0];
const comando = validos.includes(cmd) ? cmd : '/otro';
const arg = partes[1] ?? '';
const estacion_id = /^\d{1,9}$/.test(arg) ? Number(arg) : 0;
return { json: { chat_id: $json.chat_id, comando, estacion_id } };

const r = $json;
const c = $('Interpretar comando').item.json;
let texto;
switch (c.comando) {
  case '/start':
    texto = 'Hola 👋 Soy el bot de alertas de calidad del aire de EcoPredict.\n\nComandos:\n/estaciones – ver las estaciones y su número\n/suscribir N – recibir alertas de la estación N\n/baja N – dejar de recibirlas\n\nEjemplo: /suscribir 10';
    break;
  case '/estaciones':
    texto = 'Estaciones disponibles (número · nombre):\n\n' + (r.lista || 'No hay estaciones.') + '\n\nPara suscribirte: /suscribir N';
    break;
  case '/suscribir':
    if (!c.estacion_id) texto = 'Indica el número de la estación. Ejemplo: /suscribir 10\nVer los números: /estaciones';
    else if (!r.estacion) texto = `No existe la estación ${c.estacion_id}. Mira la lista con /estaciones`;
    else texto = `✅ Listo. Recibirás alertas de ${r.estacion}.\nPara dejar de recibirlas: /baja ${c.estacion_id}`;
    break;
  case '/baja':
    if (!c.estacion_id) texto = 'Indica el número de la estación. Ejemplo: /baja 10';
    else if (Number(r.bajas) === 0) texto = `No estabas suscrito a la estación ${c.estacion_id}.`;
    else texto = `Listo. Ya no recibirás alertas de ${r.estacion}.`;
    break;
  default:
    texto = 'No entendí ese comando. Usa /estaciones, /suscribir N o /baja N.';
}
return { json: { chat_id: c.chat_id, texto } };
